module BandsTest

using Test
using KernelSmoothing
using LinearAlgebra: diag, eigvals, eigen, Symmetric
using Random: MersenneTwister
using Distributions: Normal, quantile, cdf as ncdf

# covariances from nprobust 1.0.0, generated by data/covgrid_golden.R
include(joinpath(@__DIR__, "data", "covgrid_golden.jl"))

const I = 1:400
const X = round.(mod.(I .* 0.6180339887498949, 1), digits = 2)
const Y = sin.(2π .* X) .+ 0.3 .* sin.(7.3 .* I)
const W = 1.0 .+ mod.(I, 3)

@testset "covariances agree with nprobust" begin
  ev = [0.3, 0.35, 0.4, 0.7]
  for (p, ν, US, RB) in ((1, 0, COV_US_P1, COV_RB_P1), (2, 1, COV_US_P2D1, COV_RB_P2D1))
    m = fit(LocalPolynomialRegression, X, Y; degree = p, derivative = ν, bandwidth = 0.1, pilot = 0.15,
            points = ev, vce = HCVariance(0))
    @test vcov(m) ≈ US rtol = 1e-10
    @test vcov(m; method = RobustBiasCorrected()) ≈ RB rtol = 1e-10
  end
end

@testset "covariances" begin
  pts = [0.1, 0.15, 0.2, 0.5, 0.9]
  fits = Any[fit(LocalPolynomialRegression, X, Y; bandwidth = 0.08, points = pts, vce)
          for vce in (NNVariance(), HCVariance(1), HCVariance(3))]
  push!(fits, fit(LocalPolynomialRegression, X, Y; weights = W, degree = 2, derivative = 1,
                  bandwidth = 0.15, pilot = 0.2, points = pts))
  dens = Any[fit(PointwiseDensity, X; points = pts, bandwidth = 0.08, minobs = 0),
          fit(PointwiseDensity, X; weights = W, points = pts, bandwidth = 0.06, pilot = 0.1, minobs = 0,
              kernel = BiweightKernel())]
  for m in vcat(fits, dens)
    for (method, se) in ((Conventional(), m.se), (RobustBiasCorrected(), m.se_rbc))
      C = vcov(m; method)
      @test sqrt.(diag(C)) ≈ se rtol = 1e-10
      @test C ≈ C'
      @test minimum(eigvals(Symmetric(C))) >= -1e-12 * maximum(diag(C))
    end
  end
  # windows that do not overlap give uncorrelated regression estimates
  @test vcov(fits[1])[4, 5] == 0 && vcov(fits[1])[1, 4] == 0
  # density covariances by their definition
  m = dens[2]
  w, h = W, 0.06
  g(j) = BiweightKernel().((m.points[j] .- X) ./ h) ./ h
  C = vcov(m)
  for j in 1:5, l in 1:5
    cjl = sum(w .^ 2 .* (g(j) .- m.estimate[j]) .* (g(l) .- m.estimate[l])) / sum(w)^2
    @test C[j, l] ≈ cjl rtol = 1e-9 atol = 1e-14
  end
end

@testset "unidentified regression covariances" begin
  x = collect(range(0, 1; length = 101))
  y = sin.(3 .* x) .+ 0.1 .* cos.(31 .* x)
  for vce in (NNVariance(), HCVariance(0), HCVariance(1), HCVariance(2), HCVariance(3))
    m = fit(LocalPolynomialRegression, x, y; bandwidth = 0.1, points = [0.25, 5.0], vce, minobs = 0)
    valid = fit(LocalPolynomialRegression, x, y; bandwidth = 0.1, points = [0.25], vce, minobs = 0)
    @test isnan(m.se[2]) && m.nwindow[2] == 0
    for method in (Conventional(), RobustBiasCorrected())
      C = vcov(m; method)
      @test all(isnan, C[2, :]) && all(isnan, C[:, 2])
      @test C[1, 1] == vcov(valid; method)[1, 1]
      @test C[1, 1] ≈ stderror(m; method)[1]^2 rtol = 1e-12
      b = conf_band(m; method, draws = 100, rng = MersenneTwister(1))
      @test isfinite(b.lower[1]) && isfinite(b.upper[1])
      @test isnan(b.lower[2]) && isnan(b.upper[2])
    end
  end
  # A nonempty singular window is also undefined, including at disjoint points.
  xs = vcat(zeros(30), 2 .+ x)
  ys = sin.(3 .* xs) .+ 0.1 .* cos.(31 .* (1:length(xs)))
  m = fit(LocalPolynomialRegression, xs, ys; bandwidth = 0.2, points = [0.0, 2.5], minobs = 0)
  @test m.nwindow[1] == 30 && isnan(m.se[1]) && isfinite(m.se[2])
  for method in (Conventional(), RobustBiasCorrected())
    C = vcov(m; method)
    @test all(isnan, C[1, :]) && all(isnan, C[:, 1])
    @test isfinite(C[2, 2])
  end
  # A missing bias correction leaves the conventional covariance intact.
  xs = vcat(repeat([0.0, 1.0], inner = 30), 4 .+ x)
  ys = sin.(3 .* xs) .+ 0.1 .* cos.(31 .* (1:length(xs)))
  m = fit(LocalPolynomialRegression, xs, ys; bandwidth = 0.8, points = [0.5, 4.5], minobs = 0)
  @test isfinite(m.se[1]) && isnan(m.se_rbc[1]) && isfinite(m.se_rbc[2])
  @test all(isfinite, vcov(m))
  C = vcov(m; method = RobustBiasCorrected())
  @test all(isnan, C[1, :]) && all(isnan, C[:, 1]) && isfinite(C[2, 2])
end

@testset "uniform bands" begin
  # far-apart points are independent: P(max |Z| ≤ c) = (2Φ(c) - 1)^G = level
  m = fit(LocalPolynomialRegression, X, Y; bandwidth = 0.05, points = [0.1, 0.3, 0.5, 0.7, 0.9], vce = HCVariance(0))
  C = vcov(m)
  @test all(C[j, l] == 0 for j in 1:5, l in 1:5 if j != l)
  b = conf_band(m; draws = 200_000, rng = MersenneTwister(1))
  @test b.critical ≈ quantile(Normal(), (1 + 0.95^(1 / 5)) / 2) atol = 0.02
  @test b.lower ≈ m.estimate_bc .- b.critical .* m.se_rbc
  # perfectly correlated points: the pointwise critical value
  m1 = fit(LocalPolynomialRegression, X, Y; bandwidth = 0.1, points = [0.5, 0.5, 0.5])
  @test conf_band(m1; draws = 200_000, rng = MersenneTwister(2)).critical ≈ 1.959963984540054 atol = 0.02
  # in between for correlated neighbours, and reproducible with the same generator
  m2 = fit(LocalPolynomialRegression, X, Y; bandwidth = 0.1, points = range(0.2, 0.8; length = 25))
  b2 = conf_band(m2; rng = MersenneTwister(3))
  @test 1.96 < b2.critical < quantile(Normal(), 1 - 0.025 / 25)
  @test conf_band(m2; rng = MersenneTwister(3)) == b2
  @test conf_band(m2; method = Conventional(), rng = MersenneTwister(3)).upper ≈
        m2.estimate .+ conf_band(m2; method = Conventional(), rng = MersenneTwister(3)).critical .* m2.se
  # densities, and a density estimate with its own bandwidth
  f = fit(KDE, X; bandwidth = 0.08)
  md = fit(PointwiseDensity, X; points = [0.2, 0.25, 0.3], bandwidth = 0.08, minobs = 0)
  @test conf_band(f, [0.2, 0.25, 0.3]; rng = MersenneTwister(4)) == conf_band(md; rng = MersenneTwister(4))
  @test_throws ArgumentError conf_band(m2; level = 1.2)
  @test_throws ArgumentError conf_band(m2; draws = 10)
  # with one point the simulated quantile scatters around the pointwise critical value,
  # which the band never falls below
  md1 = fit(PointwiseDensity, X; points = [0.5], bandwidth = 0.08)
  @test all(conf_band(md1; rng = MersenneTwister(s)).critical >= 1.959963984540054 for s in 1:30)
end

@testset "the critical value lies between the pointwise and Bonferroni values" begin
  x = collect(range(0, 1; length = 400))
  zp = quantile(Normal(), 0.975)
  # one point: the pointwise value, exactly
  m1 = fit(LocalPolynomialRegression, x, sin.(2π .* x); bandwidth = 0.1, points = [0.5])
  @test all(conf_band(m1; rng = MersenneTwister(s)).critical == zp for s in 1:5)
  # two independent points and few draws: the simulated quantile is clamped
  m2 = fit(LocalPolynomialRegression, x, sin.(2π .* x); bandwidth = 0.1, points = [0.2, 0.8])
  zb = quantile(Normal(), 1 - 0.05 / 4)
  cs = [conf_band(m2; draws = 100, rng = MersenneTwister(s)).critical for s in 1:100]
  @test all(zp .<= cs .<= zb)
  @test any(==(zb), cs)
end

@testset "draws in blocks" begin
  # the normal variates are drawn in blocks, so that the critical value is that of a
  # loop of single draws in distribution, and the same for the same seed
  x = collect(range(0, 1; length = 400))
  m = fit(LocalPolynomialRegression, x, sin.(2π .* x); bandwidth = 0.1, points = collect(range(0.1, 0.9; length = 17)))
  C = vcov(m; method = RobustBiasCorrected())
  se = sqrt.(diag(C))
  R = C ./ (se * se')
  E = eigen(Symmetric(R))
  L = E.vectors .* sqrt.(max.(E.values, 0.0))'
  rng = MersenneTwister(3)
  maxima = [maximum(abs, L * randn(rng, 17)) for _ in 1:100_000]
  c = conf_band(m; draws = 100_000, rng = MersenneTwister(4)).critical
  @test abs(c - quantile(maxima, 0.95)) < 0.04
  @test conf_band(m; draws = 5000, rng = MersenneTwister(5)).critical == conf_band(m; draws = 5000, rng = MersenneTwister(5)).critical
  @test conf_band(m; draws = 5001, rng = MersenneTwister(5)).critical > 0
end

end
